	@Test
	void unbindableCustomExpressionFallsBackWithoutLosingRows() throws Exception {
		Function function = new Function() {
			@Override
			public String getURI() {
				return FUNCTION_IRI;
			}

			@Override
			public Determinism getDeterminism() {
				return Determinism.VOLATILE;
			}

			@Override
			@SuppressWarnings("deprecation")
			public Value evaluate(ValueFactory valueFactory, Value... arguments) {
				return valueFactory.createLiteral("custom:" + arguments[0].stringValue());
			}
		};
		FunctionRegistry.getInstance().add(function);
		try {
			Outcome result = evaluate(new FunctionCall(FUNCTION_IRI, new Var("term")), false);
			assertThat(result.first()).containsExactly("3:custom:3", "2:custom:2");
			assertThat(result.second()).containsExactly("3:custom:3", "2:custom:2");
		} finally {
			FunctionRegistry.getInstance().remove(function);
		}
	}

