	private static Outcome evaluate(ValueExpr aliasExpression, boolean workerExpected, boolean topK) throws Exception {
		List<BindingSet> input = new ArrayList<>();
		Map<Value, Long> ids = new HashMap<>();
		Map<Long, Value> terms = new HashMap<>();
		int[][] entries = { { 1, 0 }, { 2, 0 }, { 2, 0 }, { 2, 1 }, { 3, 0 },
				{ 3, 0 }, { 3, 1 }, { 4, 0 }, { 4, 0 }, { 4, 1 } };
		for (int[] entry : entries) {
			Value term = VF.createLiteral(entry[0]);
			Value bucket = VF.createLiteral("bucket-" + entry[1]);
			for (Value value : List.of(term, bucket)) {
				if (!ids.containsKey(value)) {
					long id = ValueIds.createId(ValueIds.T_LITERAL, ids.size() + 1L);
					ids.put(value, id);
					terms.put(id, value);
				}
			}
			MapBindingSet bindings = new MapBindingSet(2);
			bindings.addBinding("term", term);
			bindings.addBinding("bucket", bucket);
			input.add(bindings);
		}

		AtomicBoolean afterCompilation = new AtomicBoolean();
		AtomicInteger compileReads = new AtomicInteger();
		AtomicInteger reads = new AtomicInteger();
		AtomicInteger lookups = new AtomicInteger();
		BindingSetAssignment values = new BindingSetAssignment();
		values.setBindingNames(Set.of("term", "bucket"));
		values.setBindingSets((BindingSetAssignment.RepeatableBindingSetSource) () -> {
			if (afterCompilation.get()) {
				reads.incrementAndGet();
			} else {
				compileReads.incrementAndGet();
			}
			return input.iterator();
		});
		Group group = new Group(values, List.of("term", "bucket"));
		group.addGroupElement(new GroupElem("count", new Count(new Var("term"))));
		Extension extension = new Extension(group, new ExtensionElem(aliasExpression, "alias"));
		Projection projection = new Projection(extension,
				new ProjectionElemList(new ProjectionElem("term"), new ProjectionElem("alias")), true);
		projection.setVariableScopeChange(true);
		TupleExpr inner = new Slice(projection, 0, 20);
		TupleExpr ordered = topK ? new Order(new Distinct(inner), new OrderElem(new Var("term"), false))
				: new Distinct(new Order(inner, new OrderElem(new Var("term"), false)));
		Slice boundary = new Slice(ordered, 1, 2);

		NativeLmdbQuerySource.ParallelSource store = mock(NativeLmdbQuerySource.ParallelSource.class,
				CALLS_REAL_METHODS);
		when(store.idSpace()).thenReturn(store);
		when(store.valueLookupScope()).thenReturn(store);
		when(store.resultValueScope()).thenReturn(store);
		when(store.snapshotId()).thenReturn(1L);
		when(store.idOf(any(Value.class))).thenAnswer(call -> {
			if (afterCompilation.get()) {
				lookups.incrementAndGet();
			}
			return ids.getOrDefault(call.getArgument(0), UNKNOWN_ID);
		});
		when(store.lazyValue(anyLong())).thenAnswer(call -> terms.get(call.getArgument(0)));

		SyntheticValueSource firstSource = SyntheticValueSource.forEvaluation(store);
		SyntheticValueSource secondSource = SyntheticValueSource.forEvaluation(store);
		BindingSet empty = EmptyBindingSet.getInstance();
		firstSource.executionContext().initializeQueryBase(empty);
		secondSource.executionContext().initializeQueryBase(empty);
		QueryEvaluationContext firstContext = new QueryEvaluationContext.Minimal((Dataset) null);
		QueryEvaluationContext secondContext = new QueryEvaluationContext.Minimal((Dataset) null);
		LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(new EmptyTripleSource(), null,
				null, 0L, new EvaluationStatistics(), false);
		LmdbNativeAggregatePlanner planner = new LmdbNativeAggregatePlanner(firstContext, strategy, firstSource);
		planner.islandScopeChanges = true;
		LmdbFusedSipFactorizedRuntime.Session firstRoot = LmdbFusedSipFactorizedRuntime.create(81L, true);
		LmdbFusedSipFactorizedRuntime.Session secondRoot = LmdbFusedSipFactorizedRuntime.create(82L, true);
		LmdbFusedSipFactorizedRuntime.Session firstWorker = firstRoot.worker();
		LmdbFusedSipFactorizedRuntime.Session secondWorker = secondRoot.worker();
		RowState firstRow = null;
		RowState secondRow = null;
		try {
			SlotPlan compiled = planner.compileTuple(boundary, false);
			assertThat(compiled).isInstanceOf(NativeSubqueryPlan.class);
			assertThat(compileReads.get()).as("initial compilation reads the actual VALUES input").isPositive();
			NativeSubqueryPlan original = (NativeSubqueryPlan) compiled;
			assertThat(original.describe()).contains("RootPipeline", topK ? "TopK(" : "Order(", "Distinct", "Slice(");
			assertThat(NativeWorkerPlanBinder.canBind(original))
					.as("worker admission reflects the lexical child's repeatability")
					.isEqualTo(workerExpected);
			planner.layout.freeze(planner.slotNames);
			firstRow = new RowState(firstSource, planner.layout, empty);
			firstRow.fusedSession = firstWorker;
			assertThat(NativeRowSeeder.seed(firstRow.slots, planner.layout, empty, firstSource)).isTrue();
			firstRow.recomputeBoundMask();
			secondRow = new RowState(secondSource, planner.layout, empty);
			secondRow.fusedSession = secondWorker;
			assertThat(NativeRowSeeder.seed(secondRow.slots, planner.layout, empty, secondSource)).isTrue();
			secondRow.recomputeBoundMask();

			afterCompilation.set(true);
			NativeScalarPlan.WorkerContext firstWorkerContext = NativeScalarPlan.WorkerContext.forSource(firstSource,
					firstContext, firstWorker, firstSource.executionContext());
			NativeScalarPlan.WorkerContext secondWorkerContext = NativeScalarPlan.WorkerContext.forSource(secondSource,
					secondContext, secondWorker, secondSource.executionContext());
			NativeSubqueryPlan first = original;
			NativeSubqueryPlan second = original;
			if (workerExpected) {
				for (int i = 0; i < 2; i++) {
					first = original.forWorker(firstWorkerContext);
					second = original.forWorker(secondWorkerContext);
				}
			}
			int bindingReads = reads.get();
			int bindingLookups = lookups.get();
			List<String> firstResults = new ArrayList<>();
			List<String> secondResults = new ArrayList<>();
			try (RowCursor firstCursor = first.open(firstRow); RowCursor secondCursor = second.open(secondRow)) {
				while (firstCursor.next()) {
					assertThat(secondCursor.next()).isTrue();
					firstResults.add(result(firstRow));
					secondResults.add(result(secondRow));
				}
				assertThat(secondCursor.next()).isFalse();
			}
			return new Outcome(firstResults, secondResults, bindingReads, bindingLookups, reads.get() - bindingReads);
		} finally {
			if (firstRow != null) {
				firstRow.closeDecodedInputs();
			}
			if (secondRow != null) {
				secondRow.closeDecodedInputs();
			}
			firstSource.executionContext().close();
			secondSource.executionContext().close();
			firstWorker.close();
			secondWorker.close();
			firstRoot.close();
			secondRoot.close();
			assertThat(firstSource.executionContext().isClosed()).isTrue();
			assertThat(secondSource.executionContext().isClosed()).isTrue();
		}
	}

	private static String result(RowState row) {
		return ((Literal) row.view.getValue("term")).getLabel() + ":" + row.view.getValue("alias").stringValue();
	}

	private record Outcome(List<String> first, List<String> second, int bindingReads, int bindingLookups,
			int invocationReads) {
	}

	private static final class EmptyTripleSource implements TripleSource {
		@Override
		public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate, Value object,
				Resource... contexts) throws QueryEvaluationException {
			return new EmptyIteration<>();
		}

		@Override
		public ValueFactory getValueFactory() {
			return VF;
		}
	}
